// features/review.feature — Scenario: The review queue shows lowest confidence first
//
// About the test data: the extractor (backend/src/vendor_intake/services/extraction.py) only
// gives confidences of 0.95, 0.9, 0.85, 0.3 and 0.0, so no upload can produce 0.40.
// The low vendor uses 0.30 instead (an unparseable insurance expiry date). It is still the
// lowest-confidence vendor of the pair, which is what the scenario is about.
// The high vendor reaches 0.95: a reviewer approves its insurance extraction (0.90 because of
// the coverage amount), which leaves only the 0.95 W-9 and contract extractions pending.
// Other tests share this database and may have their own in-review vendors with lower
// scores. So instead of checking the global first item, the test checks that our low vendor
// comes before our high vendor and that the whole queue is sorted lowest confidence first.
import { expect, test, uniqueName, type Persona } from "../../fixtures";
import type { APIRequestContext } from "@playwright/test";

const W9 = "Legal Name: Harborline Logistics LLC\nTax ID: 84-2219067\nBusiness Type: LLC\n";
const CONTRACT = "Counterparty: Harborline Logistics LLC\nEffective Date: 2026-01-01\nExpiry Date: 2099-12-31\n";
const insurance = (expiry: string) =>
  `Insurer: Harbor Mutual\nPolicy Number: HM-55-1290\nCoverage Amount: $2,000,000\nExpiry Date: ${expiry}\n`;

async function upload(api: APIRequestContext, vendorId: string, kind: string, text: string): Promise<string> {
  const res = await api.post(`/api/vendors/${vendorId}/documents`, {
    multipart: {
      kind,
      file: { name: `${kind}.txt`, mimeType: "text/plain", buffer: Buffer.from(text, "utf-8") },
    },
  });
  expect(res.status(), await res.text()).toBe(201);
  const doc = await res.json();
  await expect
    .poll(async () => (await (await api.get(`/api/documents/${doc.id}`)).json()).status, {
      timeout: 30_000,
      message: `document ${kind} should finish extraction`,
    })
    .toBe("extracted");
  return doc.id as string;
}

async function inReviewVendor(
  member: APIRequestContext,
  prefix: string,
  insuranceText: string,
): Promise<{ id: string; insuranceDocId: string }> {
  const create = await member.post("/api/vendors", {
    data: { name: uniqueName(prefix), category: "logistics", contact_email: "ops@harborline.example.com" },
  });
  expect(create.status(), await create.text()).toBe(201);
  const vendor = await create.json();
  await upload(member, vendor.id, "w9", W9);
  await upload(member, vendor.id, "contract", CONTRACT);
  const insuranceDocId = await upload(member, vendor.id, "insurance_certificate", insuranceText);
  const submit = await member.post(`/api/vendors/${vendor.id}/submit`);
  expect(submit.status(), await submit.text()).toBe(200);
  expect((await submit.json()).status).toBe("in_review");
  return { id: vendor.id, insuranceDocId };
}

test("the review queue shows lowest confidence first", { tag: "@REV-03" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member" as Persona);
  const reviewer = await apiAs("reviewer" as Persona);

  const shaky = await inReviewVendor(member, "Shaky Co", insurance("next spring"));
  const confident = await inReviewVendor(member, "Confident Co", insurance("2099-12-31"));

  // Approve the confident vendor's 0.90 insurance extraction so its remaining pending
  // extractions (W-9 and contract) all score 0.95.
  const extRes = await member.get(`/api/documents/${confident.insuranceDocId}/extraction`);
  expect(extRes.status(), await extRes.text()).toBe(200);
  const ext = await extRes.json();
  const decision = await reviewer.post(`/api/extractions/${ext.id}/decision`, { data: { decision: "approve" } });
  expect(decision.status(), await decision.text()).toBe(200);

  // Act
  const res = await reviewer.get("/api/review-queue");

  // Assert
  expect(res.status(), await res.text()).toBe(200);
  const queue = (await res.json()) as Array<{ vendor_id: string; lowest_confidence: number }>;
  const shakyIdx = queue.findIndex((i) => i.vendor_id === shaky.id);
  const confidentIdx = queue.findIndex((i) => i.vendor_id === confident.id);
  expect(shakyIdx, JSON.stringify(queue)).toBeGreaterThanOrEqual(0);
  expect(confidentIdx, JSON.stringify(queue)).toBeGreaterThanOrEqual(0);

  expect(queue[confidentIdx].lowest_confidence).toBeCloseTo(0.95, 5);
  expect(queue[shakyIdx].lowest_confidence).toBeCloseTo(0.3, 5);
  expect(shakyIdx, "the lower-confidence vendor must come first").toBeLessThan(confidentIdx);

  // The first item has the lowest confidence in the whole queue (queue sorted ascending).
  const confidences = queue.map((i) => i.lowest_confidence);
  expect(confidences).toEqual([...confidences].sort((a, b) => a - b));
  expect(queue[0].lowest_confidence).toBeLessThanOrEqual(queue[shakyIdx].lowest_confidence);
});
